7	 * Fiscal-year arithmetic for date-derived owner values. The fiscal year starts on 1 July, so a date
8	 * on or after 1 July belongs to the fiscal year that ends in the following calendar year (e.g.
9	 * 2026-09-08 is in fiscal year 2027), while a date before 1 July belongs to the fiscal year that
10	 * ends in its own calendar year. The fiscal year is named by the calendar year in which it ends.
11	 * Used off the owner's business-day-adjusted {@code registrationDate} to expose {@code fiscalYear}
12	 * on responses and to supply the year segment of the {@link MembershipNumber} and the tenure count
13	 * in {@link MembershipPoints}.
14	 */
15	public final class FiscalYear {
16	
17	    private FiscalYear() {
18	    }
19	
20	    /**
21	     * The fiscal year (named by its ending calendar year) that {@code date} falls in: the calendar
22	     * year for dates before 1 July, or the next calendar year for dates on or after 1 July.
23	     */
24	    public static int of(LocalDate date) {
25	        return date.getMonthValue() >= Month.JULY.getValue() ? date.getYear() + 1 : date.getYear();
26	    }
27	
28	    /**
29	     * The {@code FY<YY>} label for {@code date} (YY being the last two digits of its fiscal year),
30	     * or {@code null} when the date is absent.
31	     */
32	    public static String label(LocalDate date) {
33	        if (date == null) {
34	            return null;
35	        }
36	        return String.format("FY%02d", of(date) % 100);
37	    }
38	}
